// Assembles apps/basic/basic.asm once per model (1, 3, and 4) and writes the images, as
// strings of raw bytes, to src/CompiledRoms.ts. That's the ROM for the "compiled" Basic level.
// The generated file is gitignored and regenerated before type checks, tests, and builds.
//
// Run with "npm run generateRoms -w packages/trs80-emulator".

import * as fs from "fs";
import {fileURLToPath} from "url";
import {Z80_KNOWN_LABELS} from "z80-base";
import {Asm, FileSystem} from "z80-asm";
import {asmToRawBinary} from "trs80-asm";
// Import from Config.js directly, never from the package index or from "trs80-emulator". The
// index imports Trs80.ts, which imports the very file we're generating, so going through
// it would make a fresh checkout unable to bootstrap.
import {ModelType, modelTypeAsmConstants, modelTypeToNumber} from "../src/Config.js";

const BASIC_ASM_PATH = fileURLToPath(new URL("../../../apps/basic/basic.asm", import.meta.url));
const OUTPUT_PATH = fileURLToPath(new URL("../src/CompiledRoms.ts", import.meta.url));

/**
 * The models that get a compiled ROM.
 */
const MODEL_TYPES = [ModelType.MODEL1, ModelType.MODEL3, ModelType.MODEL4];

/**
 * How many bytes of the image go in each string literal in the output file.
 */
const BYTES_PER_LITERAL = 100;

/**
 * Node fs implementation of FileSystem.
 */
class FileSystemImpl implements FileSystem {
    readBinaryFile(pathname: string): Uint8Array | undefined {
        try {
            return fs.readFileSync(pathname);
        } catch (e) {
            return undefined;
        }
    }

    readDirectory(pathname: string): string[] | undefined {
        try {
            return fs.readdirSync(pathname);
        } catch (e) {
            return undefined;
        }
    }

    readTextFile(pathname: string): string[] | undefined {
        try {
            return fs.readFileSync(pathname, "utf-8").split(/\r?\n/);
        } catch (e) {
            return undefined;
        }
    }
}

/**
 * Assemble basic.asm for the given model and return the image from address 0 through the last
 * byte, with gaps zero-filled. This includes the RAM part (BSS and the sample programs) at 0x4000
 * and up, which the emulator copies into RAM. Exits the process with errors if it doesn't assemble.
 */
function assembleForModel(modelType: ModelType): Uint8Array {
    const asm = new Asm(new FileSystemImpl());
    // Don't add the Model III ROM labels: this source is the ROM.
    asm.addKnownLabels(Z80_KNOWN_LABELS);
    for (const {name, value} of modelTypeAsmConstants(modelType)) {
        asm.addConstant(name, value);
    }

    const sourceFile = asm.assembleFile(BASIC_ASM_PATH);
    let failed = sourceFile === undefined;
    if (sourceFile === undefined) {
        console.error("Can't read " + BASIC_ASM_PATH);
    }
    for (const line of asm.assembledLines) {
        if (line.error !== undefined) {
            // The line number is 0-based, and missing for synthetic lines.
            const location = line.fileInfo.pathname +
                (line.lineNumber === undefined ? "" : ":" + (line.lineNumber + 1));
            console.error(location + ": error for Model " + modelTypeToNumber(modelType) + ": " +
                line.error + "\n    " + line.line);
            failed = true;
        }
    }
    if (failed) {
        process.exit(1);
    }

    return asmToRawBinary(0, asm);
}

/**
 * Encode the bytes as the body of a TypeScript string literal (without the quotes).
 */
function encodeBytes(bytes: Uint8Array): string {
    let s = "";
    for (const b of bytes) {
        if (b === 92) {
            // Backslash.
            s += "\\\\";
        } else if (b === 34) {
            // Double quote.
            s += "\\\"";
        } else if (b >= 32 && b < 127) {
            s += String.fromCharCode(b);
        } else {
            s += "\\x" + b.toString(16).padStart(2, "0");
        }
    }
    return s;
}

/**
 * Generate the TypeScript source for one exported constant holding the image as a string, split
 * into concatenated literals so that no line is enormous.
 */
function generateConstant(name: string, image: Uint8Array): string[] {
    const lines: string[] = [];
    lines.push("export const " + name + " =");
    if (image.length === 0) {
        lines.push("    \"\";");
    }
    for (let i = 0; i < image.length; i += BYTES_PER_LITERAL) {
        const literal = encodeBytes(image.subarray(i, i + BYTES_PER_LITERAL));
        const isLast = i + BYTES_PER_LITERAL >= image.length;
        lines.push("    \"" + literal + "\"" + (isLast ? ";" : " +"));
    }
    return lines;
}

/**
 * Assemble the ROMs and write the output file if its content changed.
 */
function main(): void {
    const lines: string[] = [];
    lines.push("// Generated by tools/GenerateCompiledRoms.ts from apps/basic/basic.asm. Do not modify.");
    for (const modelType of MODEL_TYPES) {
        lines.push("");
        lines.push(... generateConstant("model" + modelTypeToNumber(modelType) + "CompiledRom",
            assembleForModel(modelType)));
    }
    lines.push("");
    const content = lines.join("\n");

    let oldContent: string | undefined;
    try {
        oldContent = fs.readFileSync(OUTPUT_PATH, "utf-8");
    } catch (e) {
        oldContent = undefined;
    }
    if (content !== oldContent) {
        fs.writeFileSync(OUTPUT_PATH, content);
        console.log("Wrote src/CompiledRoms.ts");
    }
}

main();
